"""Compile the bounded v5.0 chapter-one adaptation; semantically parsed with stage directions."""
from pathlib import Path
import json, re, hashlib

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / '海风与布丁_第一季_全卷_v5.0.md'
lines = source.read_text(encoding='utf-8-sig').splitlines()

out = [
    '# Generated by tools/build_chapter.py. Edit the compiler or manuscript, not this file.',
    'label start:',
    '    $ affection = 0',
    '    $ choices_taken = []',
    '    $ looking_away = False',
    '    show screen chapter_hud'
]
mapping = []

def quote(s, allow_pause=False):
    if not allow_pause:
        s = s.replace('[', '[[').replace('{', '{{')
    else:
        s = s.replace('[', '[[')
    return json.dumps(s, ensure_ascii=False)

def emit(s, indent=4):
    out.append(' ' * indent + s)

def segment(start, end, indent=4):
    for n in range(start, end+1):
        if n > len(lines):
            break
        s = lines[n-1].strip()
        mapping.append({'source_line': n, 'generated_line': len(out)+1})
        if not s or s.startswith(('━', '——', '（→', '【CG预留】', '【事件】', '上缘深蓝紫')):
            continue
        emit('# source line %d' % n, indent)
        if s.startswith('【场景】'):
            mood = 'golden' if '黄昏前' in s else 'dusk' if '黄昏' in s else 'afternoon' if '午后' in s else 'day'
            emit('scene bg %s with dissolve' % mood, indent)
            emit('$ scene_caption = ' + quote(s[4:]), indent)
        elif s.startswith('【BGM】'):
            emit('$ music_cue = ' + quote(s[5:]), indent)
            emit('$ apply_music_cue(music_cue)', indent)
        elif s.startswith('【立绘】'):
            emit('$ portrait_cue = ' + quote(s[4:]), indent)
            if '初登场' in s:
                emit('$ persistent.cg001 = True', indent)
        elif s.startswith('◆'):
            m = re.search(r'好感度([+-]\d+)', s)
            if not m: raise ValueError((n, s))
            emit('$ affection += ' + m[1], indent)
        elif s.startswith('※'):
            emit('tail ' + quote(s[1:]), indent)
        elif s.startswith('旁白：'):
            text = s[3:]
            if '回到帐篷的时候' in text:
                emit('scene bg camp with dissolve', indent)
                emit('$ scene_caption = "帐篷外 · 黄昏"', indent)
            
            # Pacing and dramatic camera feedback
            if text == '啪！':
                emit(quote(text), indent)
                emit('with hpunch', indent)
            elif '倒飞出去三米' in text or '拍得横着飞出去三米' in text:
                emit(quote(text), indent)
                emit('with vpunch', indent)
            elif '第二记尾击' in text:
                emit('with hpunch', indent)
                emit(quote(text), indent)
            elif '拍平在水面上' in text:
                emit('with vpunch', indent)
                emit(quote(text), indent)
            elif '水花拍了我一脸' in text:
                emit('with vpunch', indent)
                emit(quote(text), indent)
            elif text == '撑着细软的水底想要站起来——指尖冷不防碰到了一样东西。':
                emit(quote('撑着细软的水底想要站起来——{w=0.4}指尖冷不防碰到了一样东西。', allow_pause=True), indent)
            elif text == '凉的。滑的。带着细腻紧致的鳞片纹路。':
                emit(quote('凉的。{w=0.3}滑的。{w=0.3}带着细腻紧致的鳞片纹路。', allow_pause=True), indent)
            elif text == '顺着指缝，轻轻滑了一下。':
                emit(quote('顺着指缝，{w=0.3}轻轻滑了一下。', allow_pause=True), indent)
            else:
                emit(quote(text), indent)
        elif s.startswith('鲸鱼小姐「'):
            raw = s[len('鲸鱼小姐「'):-1]
            if raw == '——！！':
                emit('whale ' + quote('——！！'), indent)
                emit('with hpunch', indent)
            elif raw.startswith('你刚才，摸的是本小姐的尾巴尖'):
                emit('whale ' + quote('人类。{w=0.4}你刚才，摸的是本小姐的尾巴尖。', allow_pause=True), indent)
            elif '酸梅汤里要加桂花！' in raw and '扔进深海！' in raw:
                emit('whale ' + quote('酸梅汤里要加桂花！{w=0.3}不加的话，连人带壶一起扔进深海！', allow_pause=True), indent)
            else:
                emit('whale ' + quote(raw), indent)
        elif s.startswith('我：「'):
            emit('hero ' + quote(s[len('我：「'):-1]), indent)
        elif s.startswith('（尾鳍'):
            emit('tail ' + quote(s.strip('（）')), indent)
        else:
            raise ValueError('Unclassified source line %d: %s' % (n,s))

# Dynamically parse chapter structure without fragile hardcoded line numbers
def parse_structure():
    start_line = None
    for i, line in enumerate(lines):
        if line.strip().startswith('【场景】浅滩 · 正午'):
            start_line = i + 1
            break
    assert start_line is not None

    menus = []
    i = start_line - 1
    while i < 450 and i < len(lines):
        line = lines[i].strip()
        if line == '（选项）':
            menu_line = i + 1
            opts = []
            j = i + 1
            while len(opts) < 3:
                if lines[j].strip().startswith(('A ', 'B ', 'C ')):
                    opts.append(j + 1)
                j += 1
            
            branch_a_start = None
            branch_a_end = None
            branch_b_start = None
            branch_b_end = None
            branch_c_start = None
            branch_c_end = None
            following_start = None
            
            k = j
            while k < len(lines):
                s = lines[k].strip()
                if s.startswith('——A线'):
                    branch_a_start = k + 2
                elif s.startswith('——B线'):
                    branch_a_end = k
                    branch_b_start = k + 2
                elif s.startswith('——C线'):
                    branch_b_end = k
                    branch_c_start = k + 2
                elif (branch_c_start and not branch_c_end) and (s.startswith(('——汇合', '【事件】', '【场景】浅滩 · 黄昏前'))):
                    branch_c_end = k
                    if s.startswith(('【事件】', '【场景】')):
                        following_start = k + 1
                    else:
                        following_start = k + 2
                    break
                k += 1
            
            k2 = following_start
            following_end = None
            while k2 < len(lines):
                s2 = lines[k2-1].strip()
                if s2 == '（选项）':
                    following_end = k2 - 1
                    break
                elif s2.startswith('【第一话完】'):
                    following_end = k2 - 2
                    break
                k2 += 1
            
            branches = [
                (branch_a_start, branch_a_end),
                (branch_b_start, branch_b_end),
                (branch_c_start, branch_c_end)
            ]
            menus.append((menu_line, opts, branches, (following_start, following_end)))
            i = k2 - 1
        else:
            i += 1
    return start_line, menus

start_line, menus = parse_structure()
first_menu_line = menus[0][0]
segment(start_line, first_menu_line - 1)

for index, (line, options, branches, following) in enumerate(menus, 1):
    emit('menu:')
    for k, (option, span) in enumerate(zip(options, branches)):
        text = lines[option-1].strip()[2:].strip().strip('「」')
        emit(quote(text) + ':', 8)
        emit('$ choices_taken.append(%s)' % quote('%d%s' % (index, 'ABC'[k])), 12)
        if index == 3:
            emit('$ looking_away = %s' % (k == 1), 12)
        segment(*span, indent=12)
    segment(*following)

emit('$ persistent.chapter_one_complete = True')
emit('$ renpy.save("auto-chapter-one", extra_info="SP-001 酸梅汤·加桂花")')
emit('hide screen chapter_hud')
emit('call screen chapter_end')
emit('return')

game = ROOT / 'Seabreeze' / 'game'
(game / 'chapter01.rpy').write_text('\n'.join(out) + '\n', encoding='utf-8')
(ROOT / 'tools' / 'source_map.json').write_text(
    json.dumps({'sha256': hashlib.sha256(source.read_bytes()).hexdigest(), 'mapping': mapping}, ensure_ascii=False, indent=2),
    encoding='utf-8'
)
print('Compiled chapter one successfully! Total lines:', len(out))
